// Compare pre-fix (master) and post-fix total. Not part of the change.
import { total as before } from './cart.before.mjs';
import { total as after } from '../src/cart.js';
let seed = 12345;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
let n0 = 0, diff0 = 0, nD = 0, sameD = 0, wrongD = 0;
for (let i = 0; i < 200000; i++) {
  const len = rnd(25);
  const items = Array.from({ length: len }, () => ({ price: rnd(100000), qty: rnd(20) }));
  // rate 0 (explicit and default): must be identical
  n0++;
  if (before(items, 0) !== after(items, 0) || before(items) !== after(items)) diff0++;
  // rate > 0: after must equal an independently written expected value
  const rate = [0.05, 0.1, 0.15, 0.2, 0.25, 0.5][rnd(6)];
  const sub = items.reduce((s, it) => s + it.price * it.qty, 0);
  const afterCustomer = sub * (1 - rate);
  const expected = Math.round(len >= 10 ? afterCustomer * 0.95 : afterCustomer);
  nD++;
  if (before(items, rate) === after(items, rate)) sameD++;
  if (Math.abs(after(items, rate) - expected) > 1) wrongD++;
}
console.log(`rate 0: ${n0} carts, differing = ${diff0}`);
console.log(`rate>0: ${nD} carts, before===after = ${sameD} (subtotal 0 etc.), after off from expected by >1 = ${wrongD}`);
console.log('AC1', after([{ price: 1000, qty: 1 }], 0.1), 'AC2', after(Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 })), 0.1));
console.log('raw 10000*(1-0.1)*(1-0.05) =', 10000 * (1 - 0.1) * (1 - 0.05));

