import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// n lines of the same price, qty 1 each.
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

// Issue #12, AC3: a discount rate of 0 leaves the total as it was.
test('total with discount rate 0 only gets the bulk discount', () => {
  // 9 lines, subtotal 1,000: no bulk discount.
  assert.equal(total([...lines(8, 100), { price: 200, qty: 1 }], 0), 1000);
  // 10 lines, subtotal 10,000: 5% bulk discount only -> 9,500.
  assert.equal(total(lines(10, 1000), 0), 9500);
});

// Issue #12, AC1: the customer discount is applied once.
test('customer discount is applied once on a cart under 10 lines', () => {
  // 9 lines, subtotal 1,000, rate 0.1 -> 900 (no bulk discount).
  assert.equal(total([...lines(8, 100), { price: 200, qty: 1 }], 0.1), 900);
});

// Issue #12, AC2: the 5% bulk discount comes after the customer discount, once.
test('bulk discount is applied once after the customer discount on 10 lines', () => {
  // 10 lines, subtotal 10,000, rate 0.1 -> 9,000 -> 5% off -> 8,550.
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
